import React, { useState } from 'react';
import MeshSphere from '../components/MeshSphere';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'01', label:'Väldigt dåligt', sub:'Heavy', speed:0.15, distort:1.8 },
  { score:2, emoji:'02', label:'Dåligt',         sub:'Low',   speed:0.2,  distort:1.4 },
  { score:3, emoji:'03', label:'Okej',           sub:'Neutral',speed:0.4, distort:0.8 },
  { score:4, emoji:'04', label:'Bra',            sub:'Good',  speed:0.6,  distort:0.5 },
  { score:5, emoji:'05', label:'Väldigt bra',    sub:'Flow',  speed:0.9,  distort:0.2 },
];
const REAL_EMOJIS = ['😔','😟','😐','🙂','😄'];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [selected, setSelected] = useState(null);
  const [note,     setNote]     = useState('');
  const [step,     setStep]     = useState('pick'); // pick | note | done

  const handleSave = () => {
    const m = MOODS[selected];
    addMood(m.score, REAL_EMOJIS[selected], m.label, note);
    setStep('done');
  };

  if (todayChecked && step !== 'done') return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px' }}>
      <MeshSphere size={200} speed={0.3} distort={0.4} />
      <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.3)', marginTop:24, marginBottom:12 }}>Status · 200 OK</div>
      <h2 style={{ fontSize:32, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:12 }}>Incheckad</h2>
      <p style={{ fontSize:13, color:'rgba(242,240,235,0.4)', marginBottom:36, textAlign:'center', fontWeight:300 }}>Kom tillbaka imorgon.</p>
      <div style={{ display:'flex', gap:8 }}>
        <button onClick={()=>setPage('history')} style={{ padding:'12px 20px', border:'1px solid rgba(255,255,255,0.15)', borderRadius:4, background:'#f2f0eb', color:'#0c0c0e', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', fontWeight:700 }}>Historik</button>
        <button onClick={()=>setPage('home')} style={{ padding:'12px 20px', border:'1px solid rgba(255,255,255,0.08)', borderRadius:4, color:'rgba(242,240,235,0.45)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Hem</button>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 20px' }}>
      <MeshSphere size={220} speed={MOODS[selected].speed} distort={MOODS[selected].distort} />
      <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.3)', marginTop:24, marginBottom:12 }}>Check-in · Sparat</div>
      <h2 style={{ fontSize:36, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb', marginBottom:24 }}>{MOODS[selected].label}</h2>
      <div style={{ display:'flex', gap:8 }}>
        <button onClick={()=>setPage('history')} style={{ padding:'12px 20px', border:'none', borderRadius:4, background:'#f2f0eb', color:'#0c0c0e', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase', fontWeight:700 }}>Historik</button>
        <button onClick={()=>setPage('home')} style={{ padding:'12px 20px', border:'1px solid rgba(255,255,255,0.08)', borderRadius:4, color:'rgba(242,240,235,0.45)', fontSize:11, fontFamily:'DM Mono,monospace', letterSpacing:'0.12em', textTransform:'uppercase' }}>Hem</button>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80 }}>
      <div style={{ padding:'24px 20px', maxWidth:480, margin:'0 auto', animation:'fadeUp .5s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:28 }}>
          <MeshSphere size={200} speed={MOODS[selected].speed} distort={MOODS[selected].distort} />
        </div>

        <div style={{ display:'flex', alignItems:'baseline', gap:12, marginBottom:8 }}>
          <span style={{ fontFamily:'DM Mono,monospace', fontSize:32, fontWeight:500, color:'rgba(242,240,235,0.2)', letterSpacing:'-0.02em' }}>{MOODS[selected].emoji}</span>
          <h2 style={{ fontSize:28, fontWeight:900, letterSpacing:'-0.04em', textTransform:'uppercase', color:'#f2f0eb' }}>{MOODS[selected].label}</h2>
        </div>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', color:'rgba(242,240,235,0.3)', marginBottom:28, textTransform:'uppercase' }}>{MOODS[selected].sub}</p>

        <div style={{ position:'relative', border:'1px solid rgba(255,255,255,0.1)', borderRadius:4, padding:'14px 16px', background:'rgba(255,255,255,0.03)', marginBottom:14 }}>
          <div style={{ position:'absolute', top:0, left:0, width:10, height:10, borderTop:'1.5px solid rgba(255,255,255,0.35)', borderLeft:'1.5px solid rgba(255,255,255,0.35)' }} />
          <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:10 }}>Notering (valfri)</div>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag?"
            style={{ width:'100%', background:'transparent', border:'none', color:'#f2f0eb', fontSize:14, fontWeight:300, resize:'none', height:80, outline:'none', lineHeight:1.7 }} />
        </div>
        <button onClick={handleSave} style={{ width:'100%', padding:'14px', borderRadius:4, background:'#f2f0eb', color:'#0c0c0e', fontSize:12, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.16em', textTransform:'uppercase', marginBottom:8 }}>Spara →</button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'10px', fontSize:11, color:'rgba(242,240,235,0.3)', fontFamily:'DM Mono,monospace', letterSpacing:'0.1em', textTransform:'uppercase' }}>← Ändra</button>
      </div>
    </div>
  );

  // Main pick screen
  return (
    <div style={{ minHeight:'100vh', background:'#0c0c0e', paddingTop:56, paddingBottom:80, position:'relative' }}>
      <div style={{ position:'absolute', inset:0, backgroundImage:'linear-gradient(rgba(255,255,255,0.02) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.02) 1px, transparent 1px)', backgroundSize:'48px 48px', pointerEvents:'none' }} />

      <div style={{ padding:'24px 20px', position:'relative', zIndex:1 }}>
        <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.24em', textTransform:'uppercase', color:'rgba(242,240,235,0.28)', marginBottom:8 }}>Daglig check-in</div>
        <h1 style={{ fontSize:'clamp(36px,9vw,56px)', fontWeight:900, letterSpacing:'-0.06em', lineHeight:0.86, color:'#f2f0eb', textTransform:'uppercase', marginBottom:32 }}>
          HUR<br/>MÅR DU?
        </h1>

        {/* Mood selector — horizontal with mesh preview */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32, height:160, alignItems:'center', position:'relative' }}>
          {selected !== null ? (
            <MeshSphere size={160} speed={MOODS[selected].speed} distort={MOODS[selected].distort} key={selected} />
          ) : (
            <div style={{ width:160, height:160, border:'1px solid rgba(255,255,255,0.06)', borderRadius:'50%', display:'flex', alignItems:'center', justifyContent:'center' }}>
              <span style={{ fontFamily:'DM Mono,monospace', fontSize:10, color:'rgba(242,240,235,0.2)', letterSpacing:'0.16em', textTransform:'uppercase' }}>Välj</span>
            </div>
          )}
        </div>

        {/* Mood rows */}
        <div style={{ display:'flex', flexDirection:'column', gap:3 }}>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            return (
              <button key={m.score} onClick={()=>setSelected(idx)}
                style={{ display:'flex', alignItems:'center', justifyContent:'space-between', padding:'14px 16px', border:`1px solid ${isSel?'rgba(242,240,235,0.2)':'rgba(255,255,255,0.06)'}`, borderRadius:4, background:isSel?'rgba(242,240,235,0.06)':'transparent', transition:'all .2s' }}>
                <div style={{ display:'flex', alignItems:'center', gap:16 }}>
                  <span style={{ fontFamily:'DM Mono,monospace', fontSize:13, fontWeight:500, color:isSel?'rgba(242,240,235,0.7)':'rgba(242,240,235,0.2)', minWidth:24, letterSpacing:'-0.02em' }}>{m.emoji}</span>
                  <div>
                    <div style={{ fontSize:14, fontWeight:isSel?700:400, color:isSel?'#f2f0eb':'rgba(242,240,235,0.6)', letterSpacing:'-0.01em', transition:'all .2s' }}>{m.label}</div>
                    <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(242,240,235,0.25)', letterSpacing:'0.12em', textTransform:'uppercase', marginTop:1 }}>{m.sub}</div>
                  </div>
                </div>
                <span style={{ fontSize:12, color:'rgba(242,240,235,0.2)', opacity:isSel?1:0, transition:'opacity .2s' }}>→</span>
              </button>
            );
          })}
        </div>

        <button onClick={()=>setStep('note')} disabled={selected===null}
          style={{ width:'100%', marginTop:16, padding:'14px', borderRadius:4, background:selected!==null?'#f2f0eb':'rgba(255,255,255,0.06)', color:selected!==null?'#0c0c0e':'rgba(242,240,235,0.2)', fontSize:12, fontWeight:700, fontFamily:'DM Mono,monospace', letterSpacing:'0.16em', textTransform:'uppercase', transition:'all .3s' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}
